export const articlesContent = { 
  tr,
 };

 export function getArticles(locale = 'tr') {
  const baseList = articlesContent.tr;

  if (locale === 'tr') {
    return baseList;
  }

  return baseList.map((item) => {
    const translation = articleLocaleContent[locale]?.[item.slug];

    // Çeviri yoksa Türkçe makaleyi olduğu gibi göster.
    if (!translation) {
      return item;
    }

    return {
      ...item,
      ...translation,
      // Çevrilmiş bölümler yoksa Türkçe bölümleri koru.
      sections: translation.sections ?? item.sections,
      list: translation.list ?? item.list,
      listIntro: translation.listIntro ?? item.listIntro,
      outro: translation.outro ?? item.outro,
    };
  });
}

export function getArticleBySlug(slug, locale = 'tr') {
  const list = getArticles(locale);
  return list.find((item) => item.slug === slug) || null;
}